import { useRef } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import type { SessionDTO } from '@cli-run-ui/core';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

interface SessionListProps {
  sessions: SessionDTO[];
  activeUid: string | null;
  onSelect: (uid: string) => void;
}

export function SessionList({ sessions, activeUid, onSelect }: SessionListProps) {
  const parentRef = useRef<HTMLDivElement | null>(null);
  const rowVirtualizer = useVirtualizer({
    count: sessions.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 108,
    overscan: 8,
  });

  return (
    <div ref={parentRef} className="relative h-[52vh] overflow-auto pr-2">
      {sessions.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-white/10 bg-black/20 px-4 py-8 text-center text-sm text-slate-400">
          No sessions match the current filter.
        </div>
      ) : null}
      <div className="relative w-full" style={{ height: rowVirtualizer.getTotalSize() }}>
        {rowVirtualizer.getVirtualItems().map((virtualRow) => {
          const session = sessions[virtualRow.index];
          const isActive = session.uid === activeUid;
          return (
            <button
              key={session.uid}
              className={cn(
                'absolute left-0 w-full rounded-2xl border px-4 py-3 text-left transition',
                isActive
                  ? 'border-cyan-300/40 bg-cyan-300/[0.11] shadow-[0_12px_32px_rgba(45,212,191,0.12)]'
                  : 'border-white/10 bg-white/[0.03] hover:bg-white/[0.07]'
              )}
              onClick={() => onSelect(session.uid)}
              style={{ transform: `translateY(${virtualRow.start}px)` }}
              ref={rowVirtualizer.measureElement}
              data-index={virtualRow.index}
            >
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <Badge className={providerBadgeClass(session.provider)}>
                      {session.provider}
                    </Badge>
                    {session.status ? (
                      <Badge
                        variant="muted"
                        className="border-white/10 bg-white/[0.04] text-slate-300"
                      >
                        {session.status}
                      </Badge>
                    ) : null}
                  </div>
                  <div className="mt-2 truncate text-sm font-semibold text-white">
                    {session.title}
                  </div>
                  <div className="mt-1 truncate text-xs text-slate-400">
                    {session.projectPath ?? session.projectName}
                  </div>
                </div>
                <div
                  className={cn(
                    'mt-1 h-2.5 w-2.5 rounded-full',
                    isActive ? 'bg-cyan-300 shadow-[0_0_14px_rgba(103,232,249,0.85)]' : 'bg-slate-600'
                  )}
                />
              </div>

              <div className="mt-3 grid grid-cols-2 gap-2 text-xs text-slate-400">
                <div className="rounded-xl border border-white/10 bg-black/20 px-2.5 py-2">
                  <div className="uppercase tracking-[0.18em] text-[10px] text-slate-500">
                    Updated
                  </div>
                  <div className="mt-1 text-slate-200">{formatRelative(session.updatedAtMs)}</div>
                </div>
                <div className="rounded-xl border border-white/10 bg-black/20 px-2.5 py-2">
                  <div className="uppercase tracking-[0.18em] text-[10px] text-slate-500">
                    Tokens
                  </div>
                  <div className="mt-1 text-slate-200">
                    {formatUsage(session.usage) ?? 'n/a'}
                  </div>
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function providerBadgeClass(provider: SessionDTO['provider']) {
  return provider === 'claude'
    ? 'border-sky-400/30 bg-sky-400/10 text-sky-100'
    : 'border-emerald-400/30 bg-emerald-400/10 text-emerald-100';
}

function formatUsage(usage?: SessionDTO['usage']): string | null {
  if (!usage) return null;
  if (typeof usage.total === 'number') return compactNumber(usage.total);
  const total = (usage.input ?? 0) + (usage.output ?? 0);
  return total > 0 ? compactNumber(total) : null;
}

function compactNumber(value: number): string {
  return new Intl.NumberFormat(undefined, {
    notation: value >= 1000 ? 'compact' : 'standard',
    maximumFractionDigits: 1,
  }).format(value);
}

function formatRelative(timestampMs: number): string {
  const diff = Date.now() - timestampMs;
  if (diff < 60_000) return 'just now';
  if (diff < 3_600_000) return `${Math.round(diff / 60_000)}m ago`;
  if (diff < 86_400_000) return `${Math.round(diff / 3_600_000)}h ago`;
  return `${Math.round(diff / 86_400_000)}d ago`;
}
